CREATE OR REPLACE FUNCTION public.log_user_activity(_user_id uuid,_action text,_description text DEFAULT NULL,_ip_address text DEFAULT NULL,_user_agent text DEFAULT NULL,_metadata jsonb DEFAULT '{}'::jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 -- Auth lifecycle is the sole source of login entries; legacy callers cannot duplicate or forge them.
 IF _action='login' THEN RETURN; END IF;
 INSERT INTO public.user_activity_log(user_id,action,description,ip_address,user_agent,metadata) VALUES(_user_id,_action,_description,_ip_address::inet,_user_agent,_metadata); END $$;
CREATE OR REPLACE FUNCTION public.um_history_options() RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT jsonb_build_object('roles',coalesce((SELECT jsonb_agg(x ORDER BY x.name) FROM(SELECT l.role_id id,coalesce(max(r.name),max(btrim(l.role_name)),'Removed role') name FROM public.permission_change_log l LEFT JOIN public.roles r ON r.id=l.role_id WHERE l.role_id IS NOT NULL GROUP BY l.role_id)x),'[]'::jsonb),'actors',coalesce((SELECT jsonb_agg(x ORDER BY x.name) FROM(SELECT DISTINCT l.changed_by id,coalesce(nullif(btrim(concat(u.first_name,' ',u.last_name)),''),u.username,'Removed account') name FROM public.permission_change_log l LEFT JOIN public.users u ON u.id=l.changed_by WHERE l.changed_by IS NOT NULL)x),'[]'::jsonb)) $$;
REVOKE ALL ON FUNCTION public.um_history_options() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.um_history_options() TO authenticated;